exercise.solution:
fn first_even(numbers: &[i32]) -> Option<i32> {
    for &n in numbers {
        if n % 2 == 0 {
            return Some(n);
        }
    }
    None
}

fn main() {
    let result = first_even(&[3, 7, 8, 10]);
    println!("{}", result.unwrap_or(0));
}
